import React, { useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { setAudience } from '../utils/audience';

/**
 * Selector a pantalla completa
 * - Hover marca TODO el cuadrante.
 * - El logo “vuela” y ENCAJA con el logo grande del HERO de la Home.
 * - Navega recién después de terminar la animación.
 */
export default function AudienceGate() {
  const nav = useNavigate();
  const loc = useLocation();
  const rootRef = useRef(null);
  const logoRef = useRef(null);
  const targetRef = useRef(null);

  const choose = (audValue) => {

    // persistir audiencia + header para backend
    setAudience(audValue);
    axios.defaults.headers.common['X-Audience'] = audValue;

    // origen y destino (destino = proxy con el frame EXACTO del hero)
    const src = logoRef.current.getBoundingClientRect();
    const tgt = targetRef.current.getBoundingClientRect();

    // clon volador (para que no parpadee el logo real)
    const flyer = logoRef.current.cloneNode(true);
    flyer.className = 'ag-fly';
    Object.assign(flyer.style, {
      left: `${src.left}px`,
      top: `${src.top}px`,
      width: `${src.width}px`,
      height: `${src.height}px`,
    });
    document.body.appendChild(flyer);

    // tenue fade del fondo durante la animación
    rootRef.current?.classList.add('ag-animating');

    // animar al “frame” final del hero (mismo tamaño/posición)
    requestAnimationFrame(() => {
      Object.assign(flyer.style, {
        left: `${tgt.left}px`,
        top: `${tgt.top}px`,
        width: `${tgt.width}px`,
        height: `${tgt.height}px`,
        opacity: '1',
      });
    });

    const to =
      loc.state && loc.state.from
        ? loc.state.from.pathname + (loc.state.from.search || '')
        : '/';

    const done = () => {
      flyer.removeEventListener('transitionend', done);
      flyer.remove();
      nav(to, { replace: true });
    };
    flyer.addEventListener('transitionend', done);
    // fallback
    setTimeout(done, 600);
  };

  return (
    <div className="ag-root" ref={rootRef}>
      {/* Proxy invisible: replica el frame del logo del HERO (Home) */}
      <div className="ag-hero-proxy">
        <div className="ag-hero-proxy-inner">
          <span className="ag-hero-logo" ref={targetRef} aria-hidden>
            <img src="/logo.png" alt="" />
          </span>
        </div>
      </div>

      {/* Logo grande del selector (mismo ratio que el hero) */}
      <div className="ag-logo-wrap">
        <img ref={logoRef} src="/logo.png" alt="Conecta Pinamar" className="ag-logo" />
        <div className="ag-underline" />
      </div>

      {/* Dos cuadrantes con hover de bloque completo */}
      <div className="ag-split">
        <button className="ag-side ag-left" onClick={() => choose('TOURIST')}>
          <span className="ag-label">Soy Turista</span>
        </button>
        <button className="ag-side ag-right" onClick={() => choose('RESIDENT')}>
          <span className="ag-label">Soy Residente</span>
        </button>
      </div>
    </div>
  );
}
